fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(6) == 0 {
        host::display::state_set(6, 1);
        host::display::state_set(0, w / 2 - 20);
        host::display::state_set(1, 60);
    }
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(5);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut x: i32 = host::display::state_get(0);
    let mut y: i32 = host::display::state_get(1);
    let mut drag: i32 = host::display::state_get(2);
    if down == 1 && prev == 0 && px >= x && px < x + 40 && py >= y && py < y + 40 {
        drag = 1;
        host::display::state_set(3, px - x);
        host::display::state_set(4, py - y);
    }
    if drag == 1 && down == 1 {
        x = px - host::display::state_get(3);
        y = py - host::display::state_get(4);
    }
    let bw: i32 = w / 3;
    let bys: i32 = h - 100;
    let mut overbin: i32 = -1;
    if y + 20 >= bys {
        overbin = (x + 20) / bw;
        if overbin > 2 { overbin = 2; }
    }
    if drag == 1 && down == 0 {
        drag = 0;
        if overbin >= 0 {
            x = overbin * bw + bw / 2 - 20;
            y = bys + 30;
            host::display::state_set(7, overbin + 1);
        }
    }
    host::display::state_set(0, x);
    host::display::state_set(1, y);
    host::display::state_set(2, drag);
    host::display::state_set(5, down);
    host::display::clear(0x101010);
    let mut i: i32 = 0;
    while i < 3 {
        let mut bc: i32 = 0x303030;
        if drag == 1 && i == overbin { bc = 0x00aa66; }
        host::display::fill_rect(i * bw + 6, bys, bw - 12, 90, bc);
        host::display::fill_rect(i * bw + 9, bys + 3, bw - 18, 84, 0x101010);
        host::display::draw_number(i * bw + bw / 2 - 3, bys + 70, i + 1, 0x808080, 1);
        i = i + 1;
    }
    let stored: i32 = host::display::state_get(7);
    if stored > 0 && drag == 0 {
        host::display::draw_string(8, 8, "IN BIN", 0x00ff88, 1);
        host::display::draw_number(60, 8, stored, 0x00ff88, 1);
    } else {
        host::display::draw_string(8, 8, "DRAG THE TOKEN INTO A BIN", 0x808080, 1);
    }
    host::display::fill_rect(x, y, 40, 40, 0xffaa00);
    host::display::present();
}
